/**
 * Dashboard KPIs and Analytics data, derived from MOCK_RECORDS rather than typed out.
 *
 * Deriving matters here. 02-dashboard.md §1 says every KPI on the Dashboard
 * summarizes data generated by later pages, so a hand-written KPI that disagrees
 * with the records list is a bug a judge can find in ten seconds by clicking the
 * card. Everything below counts the same records the Records page shows.
 *
 * The historical trend series is the one exception and is illustrative, because
 * twelve seed records cannot describe several months of activity.
 *
 * TODO: BRD §15 Q-07 is unresolved — whether real manual-inspection baseline data
 * exists. Until it does, treat the trend series as illustrative in any demo claim.
 */

import type {
  AnalyticsData,
  AnomalyAlert,
  CategoryBreakdownEntry,
  ComplianceStatus,
  DashboardAlert,
  KpiMetric,
  RegionBreakdownEntry,
  SourceBreakdownEntry,
  TrendPoint,
  ViolationBreakdownEntry,
} from "@/types";
import { SOURCE_TAGS, VIOLATION_CATEGORY_IDS } from "@/types";

import { MOCK_ACTIVE_RECORDS } from "./records";

const total = MOCK_ACTIVE_RECORDS.length;

function countByStatus(status: ComplianceStatus): number {
  return MOCK_ACTIVE_RECORDS.filter((r) => r.complianceStatus === status).length;
}

const compliantCount = countByStatus("Compliant");
const nonCompliantCount = countByStatus("Non-Compliant");
const pendingCount = countByStatus("Pending");

const percentageOf = (count: number) =>
  total === 0 ? 0 : Math.round((count / total) * 100);

/**
 * The four Dashboard KPI cards.
 *
 * "Pending" counts records whose Verification Status is still Extracted. 02 §2 and
 * 00-README.md §A both insist this means "awaiting verification", not a vague
 * backlog, which is why its hint string says so explicitly.
 */
export const MOCK_KPIS: readonly KpiMetric[] = [
  {
    id: "productsScanned",
    value: total,
    deltaPercentage: 12,
  },
  {
    id: "compliant",
    value: compliantCount,
    percentageOfTotal: percentageOf(compliantCount),
    deltaPercentage: 4,
    routesToStatus: "Compliant",
  },
  {
    id: "nonCompliant",
    value: nonCompliantCount,
    percentageOfTotal: percentageOf(nonCompliantCount),
    deltaPercentage: 9,
    routesToStatus: "Non-Compliant",
  },
  {
    id: "pending",
    value: pendingCount,
    percentageOfTotal: percentageOf(pendingCount),
    deltaPercentage: -3,
    routesToStatus: "Pending",
  },
];

