export const MOCK_VIOLATION_BREAKDOWN: readonly ViolationBreakdownEntry[] =
  VIOLATION_CATEGORY_IDS.map((categoryId) => ({
    categoryId,
    count: MOCK_ACTIVE_RECORDS.reduce(
      (sum, record) =>
        sum + record.violations.filter((v) => v.categoryId === categoryId).length,
      0
    ),
  }));

export const MOCK_CATEGORY_BREAKDOWN: readonly CategoryBreakdownEntry[] =
  Object.values(
    MOCK_ACTIVE_RECORDS.reduce<Record<string, CategoryBreakdownEntry>>(
      (acc, record) => {
        const entry = acc[record.category] ?? {
          category: record.category,
          compliant: 0,
          nonCompliant: 0,
        };
        if (record.complianceStatus === "Compliant") entry.compliant += 1;
        if (record.complianceStatus === "Non-Compliant") entry.nonCompliant += 1;
        acc[record.category] = entry;
        return acc;
      },
      {}
    )
  );

export const MOCK_REGION_BREAKDOWN: readonly RegionBreakdownEntry[] = Object.values(
  MOCK_ACTIVE_RECORDS.reduce<Record<string, RegionBreakdownEntry>>((acc, record) => {
    const entry = acc[record.region] ?? {
      region: record.region,
      totalScanned: 0,
      nonCompliant: 0,
    };
    entry.totalScanned += 1;
    if (record.complianceStatus === "Non-Compliant") entry.nonCompliant += 1;
    acc[record.region] = entry;
    return acc;
  }, {})
);

export const MOCK_SOURCE_BREAKDOWN: readonly SourceBreakdownEntry[] = SOURCE_TAGS.map(
  (source) => ({
    source,
    count: MOCK_ACTIVE_RECORDS.filter((r) => r.source === source).length,
  })
);

